      final List<Container> actualContainers, final List<Container> desiredContainers,
      final String containerType) {
    // only sanitize if the number of containers are equal, otherwise there is a genuine change
    final var desiredSize = desiredContainers.size();
    if (desiredSize == actualContainers.size()) {
      for (int i = 0; i < desiredSize; i++) {
        final var desiredContainer = desiredContainers.get(i);
        final var actualContainer = actualContainers.get(i);
        // only sanitize if the containers are the same, otherwise there is a genuine change
        if (!desiredContainer.getName().equals(actualContainer.getName())) {
          return;
        }
        sanitizeResourceRequirements(actualMap, actualContainer.getResources(),
            desiredContainer.getResources(), containerType, i);
      }
    }
  }

  private static void sanitizeResourceRequirements(final Map<String, Object> actualMap,
      final ResourceRequirements actualResource, final ResourceRequirements desiredResource,
      final String containerType, final int containerIndex) {
    if (desiredResource == null || actualResource == null) {
      return;
